<!doctype html><html lang="id"><head><meta charset="utf-8"><style>body{font-family:DejaVu Sans,sans-serif;color:#111827}table{width:100%;border-collapse:collapse}td{padding:10px;border-bottom:1px solid #ddd}.right{text-align:right}</style></head><body><h1>Invoice {{ $invoice->invoice_number }}</h1><p>Customer: {{ $invoice->user?->name }}</p><p>Cabang: {{ $invoice->branch->name }}</p><p>Pesanan: {{ $invoice->order->order_number }}</p><table><tr><td>Pesanan custom DTF</td><td class="right">Rp {{ number_format($invoice->product_total,0,',','.') }}</td></tr><tr><td>Ongkir</td><td class="right">Rp {{ number_format($invoice->shipping_cost,0,',','.') }}</td></tr><tr><td><b>Total</b></td><td class="right"><b>Rp {{ number_format($invoice->total,0,',','.') }}</b></td></tr></table><p>Dibayar: {{ $invoice->paid_at->format('d/m/Y H:i') }}</p></body></html>
